// Local SweetAlert2 Fallback & Wrapper for Placement Pro
(function (global) {
  if (global.Swal) return;

  function SwalFire(options) {
    return new Promise((resolve) => {
      let title = '';
      let text = '';
      let icon = 'info';

      if (typeof options === 'string') {
        title = options;
      } else if (typeof options === 'object' && options !== null) {
        title = options.title || '';
        text = options.text || options.html || '';
        icon = options.icon || 'info';
      }

      if (options && options.showCancelButton) {
        const confirmed = global.confirm(`${title}${text ? '\n' + text : ''}`);
        resolve({ isConfirmed: confirmed, isDismissed: !confirmed });
      } else {
        if (title || text) {
          if (typeof showToast === 'function') {
            showToast(`${title}: ${text}`, icon === 'error' ? 'danger' : 'success');
          } else {
            global.alert(`${title}${text ? '\n' + text : ''}`);
          }
        }
        resolve({ isConfirmed: true, isDismissed: false });
      }
    });
  }

  SwalFire.fire = SwalFire;
  global.Swal = SwalFire;
})(window);
